class Solution {
public:
    std::string greatestLetter(std::string s) {
        bool seen[128] = {false};
        for (char c : s) seen[(unsigned char)c] = true;
        for (char c = 'Z'; c >= 'A'; --c) {
            if (seen[(unsigned char)c] && seen[(unsigned char)(c + 32)]) {
                return std::string(1, c);
            }
        }
        return "";
    }
};

class Solution {
    public String greatestLetter(String s) {
        boolean[] seen = new boolean[128];
        for (char c : s.toCharArray()) seen[c] = true;
        for (char c = 'Z'; c >= 'A'; c--) {
            if (seen[c] && seen[c + 32]) {
                return String.valueOf(c);
            }
        }
        return "";
    }
}

var greatestLetter = function(s) {
    const seen = new Uint8Array(128);
    for (let i = 0; i < s.length; i++) seen[s.charCodeAt(i)] = 1;
    for (let code = 90; code >= 65; code--) {
        if (seen[code] === 1 && seen[code + 32] === 1) {
            return String.fromCharCode(code);
        }
    }
    return "";
};
